@@ -18,4 +18,26 @@
 <div id="raidEnd" class="raid-end"><div><div class="eyebrow" id="endKicker">MISSION COMPLETE</div><h2 id="endTitle">EXTRACTED</h2><p id="endText"></p><button class="button" id="returnButton">RETURN TO BASE</button></div></div>
 </div>
 <section id="base"><header class="topbar"><div class="brand">OUTPOST<span>ZERO</span></div><div class="top-right"><span class="online">●&nbsp; SYSTEM ONLINE</span><span>OPERATOR // ROOKIE</span><span id="clock">LOCAL 08:42</span></div></header><main class="base-main"><div class="hero"><div class="eyebrow">SAFEHOUSE // SECTOR 9</div><h1>THE WORLD<br>IS <em>YOURS.</em></h1><p class="hero-copy">Drop into the exclusion zone. Scavenge what you can carry. Make it back alive, and every piece is yours to keep.</p><div class="status-row"><div class="stat"><label>AVAILABLE CREDITS</label><strong>₡ <span id="credits">1200</span></strong></div><div class="stat"><label>STASH VALUE</label><strong>₡ <span id="stashValue">0</span></strong></div><div class="stat"><label>EXTRACTIONS</label><strong id="extractCount">0</strong></div></div><button class="button" id="deploy">DEPLOY TO DUSTFALL &nbsp; →</button></div><div class="sidepanel"><div class="card mission-card"><div class="card-kicker"><span>AVAILABLE OPERATION</span><span class="live">● OPEN</span></div><div class="map-art"><div class="map-grid"></div></div><div class="map-title">DUSTFALL OUTSKIRTS</div><div class="map-desc">ABANDONED INDUSTRIAL DISTRICT &nbsp;·&nbsp; 12 MIN WINDOW</div><div class="mission-foot"><span class="risk">THREAT LEVEL &nbsp; <b>▲▲△</b> MODERATE</span><span class="controls">SOLO DROP</span></div></div><div class="card inventory-card"><div class="inventory-head"><strong>SAFEHOUSE STASH</strong><span id="stashCount">0 ITEMS</span></div><div id="stashList" class="loot-list"><div class="empty">No stored loot. Go find something.</div></div><div class="inventory-actions"><button class="button secondary" id="sellButton" disabled>SELL STASH · ₡0</button><button class="button secondary" id="storeButton" disabled>STORE CARRIED</button></div></div><div class="card briefing"><div class="eyebrow">FIELD MANUAL</div><p>Search supply crates and fallen patrols. Enemies are drawn to movement—aim for the head and keep moving.</p><div class="controls"><b>W A S D</b> MOVE &nbsp; <b>MOUSE</b> AIM &nbsp; <b>CLICK</b> FIRE<br><b>E</b> LOOT / EXTRACT &nbsp; <b>SHIFT</b> SPRINT &nbsp; <b>ESC</b> RELEASE</div></div></div></main><footer class="bottomline"><span>OUTPOST ZERO // FIELD OPERATIONS</span><span>EVERY RUN IS A RISK. EVERY EXTRACTION IS A WIN.</span><span>BUILD 0.9.4</span></footer></section>
 <script>
+const canvas=document.querySelector('#view'),ctx=canvas.getContext('2d');let W=0,H=0,zbuf=[];
+function resize(){W=canvas.width=innerWidth;H=canvas.height=innerHeight}addEventListener('resize',resize);resize();
+const $=s=>document.querySelector(s), rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+const catalog=[['Salvaged CPU',180,'#9cc7c0'],['Field Medkit',120,'#eb8675'],['Old Coin',65,'#d7bd67'],['Military Optic',260,'#86a8d1'],['Power Cell',150,'#d8dc75'],['Encrypted Drive',340,'#bb91dc'],['Ration Pack',45,'#c89a68'],['Gold Watch',210,'#e5bf74']];
+let save;try{save=JSON.parse(localStorage.outpostZero)||{credits:1200,stash:[],extracts:0}}catch{save={credits:1200,stash:[],extracts:0}}let carried=[];
+function persist(){localStorage.outpostZero=JSON.stringify(save);updateBase()}
+function updateBase(){ $('#credits').textContent=save.credits.toLocaleString();$('#stashValue').textContent=save.stash.reduce((n,x)=>n+x.value,0).toLocaleString();$('#extractCount').textContent=save.extracts;$('#stashCount').textContent=`${save.stash.length} ITEMS`;$('#stashList').innerHTML=save.stash.length?save.stash.map(x=>`<div class="loot-chip">${x.name} <b>₡${x.value}</b></div>`).join(''):'<div class="empty">No stored loot. Go find something.</div>';$('#sellButton').disabled=!save.stash.length;$('#sellButton').textContent=`SELL STASH · ₡${save.stash.reduce((n,x)=>n+x.value,0)}`;$('#storeButton').disabled=!carried.length;$('#storeButton').textContent=`STORE CARRIED${carried.length?` · ${carried.length}`:''}`}
+updateBase();$('#sellButton').onclick=()=>{if(!save.stash.length)return;save.credits+=save.stash.reduce((n,x)=>n+x.value,0);save.stash=[];persist();toastBase('STASH SOLD · CREDITS ADDED')};$('#storeButton').onclick=()=>{save.stash.push(...carried);carried=[];persist();toastBase('LOOT SECURED IN SAFEHOUSE')};
+function toastBase(msg){const b=$('#deploy');let old=b.textContent;b.textContent=msg;setTimeout(()=>b.textContent=old,1500)}
+const mapText=[
+'##################','##....#.....#...##','#.....#.....#....#','#..##...##.......#','#..#....#....##..#','#..#....#........#','#......##..###...#','###.......#......#','#.....#...#..##...#','#.....#......#....#','#..##...###.#.....#','#......#....#..#..#','#.####....##...#..#','#....#.........#..#','#....#..###.......#','##.............####','##################'
+];let grid=mapText.map(r=>r.split(''));const GW=grid[0].length,GH=grid.length;
+let player={x:2.5,y:2.5,a:0,hp:100,ammo:30,reserve:90},running=false,dead=false,raidStart=0,lastTime=0,fireAt=0,items=[],enemies=[],extract={x:15.5,y:14.5},damageCooldown=0,keys={},mouseLocked=false,move={f:0,s:0};
+function wall(x,y){return !grid[Math.floor(y)]||grid[Math.floor(y)][Math.floor(x)]!==' .'&&grid[Math.floor(y)][Math.floor(x)]!==' '&&grid[Math.floor(y)][Math.floor(x)]!=='..'&&grid[Math.floor(y)][Math.floor(x)]!=='.'}
+function solid(x,y){return x<0||y<0||x>=GW||y>=GH||grid[Math.floor(y)][Math.floor(x)]==='#'}
+function openCell(x,y){return !solid(x,y)}
+function makeRaid(){player={x:2.5,y:2.5,a:.18,hp:100,ammo:30,reserve:90};carried=[];items=[];enemies=[];let lootSpots=[[5.5,2.5],[10.5,2.5],[14.5,4.5],[2.5,7.5],[6.5,8.5],[11.5,7.5],[15.5,9.5],[4.5,12.5],[8.5,14.5],[13.5,13.5]];lootSpots.forEach((p,i)=>items.push({x:p[0],y:p[1],type:'loot',item:catalog[(Math.random()*catalog.length)|0],taken:false}));let guards=[[7.5,4.5],[12.5,5.5],[4.5,9.5],[9.5,10.5],[14.5,12.5],[6.5,14.5]];guards.forEach((p,i)=>enemies.push({x:p[0],y:p[1],a:Math.PI,alive:true,hp:2,alert:0,shot:rand(0,1.3),wander:rand(0,6),homeX:p[0],homeY:p[1]}));items.push({x:extract.x,y:extract.y,type:'extract',taken:false});raidStart=performance.now();dead=false;$('#base').style.display='none';$('#hud').style.display='block';$('#raidEnd').style.display='none';$('#mobile').style.display=innerWidth<850?'block':'none';updateHud();requestPointer()}
+$('#deploy').onclick=()=>makeRaid();$('#returnButton').onclick=()=>{running=false;$('#raidEnd').style.display='none';$('#hud').style.display='none';$('#mobile').style.display='none';$('#base').style.display='flex';updateBase()};
+function requestPointer(){if(innerWidth>850)canvas.requestPointerLock?.()}
+document.addEventListener('pointerlockchange',()=>mouseLocked=document.pointerLockElement===canvas);
+addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE'&&!e.repeat)interact();if(e.code==='KeyR'&&running)reload();if(e.code==='Escape'&&running&&mouseLocked)document.exitPointerLock()});addEventListener('keyup',e=>keys[e.code]=false);
+document.addEventListener('mousemove',e=>{if(running&&mouseLocked)player.a+=e.movementX*.0025});canvas.addEventListener('mousedown',e=>{if(!running)return;if(!mouseLocked&&innerWidth>850){requestPointer();return}if(e.button===0)shoot()});canvas.addEventListener('contextmenu',e=>e.preventDefault());

