document.addEventListener('mousemove',e=>{if(running&&mouseLocked)player.a+=e.movementX*.0025});canvas.addEventListener('mousedown',e=>{if(!running)return;if(!mouseLocked&&innerWidth>850){requestPointer();return}if(e.button===0)shoot()});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function drawWorld(){
 let horizon=H*.49;let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#1b2825');sky.addColorStop(.7,'#66736a');sky.addColorStop(1,'#b1a183');ctx.fillStyle=sky;ctx.fillRect(0,0,W,horizon);let floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,'#615f4f');floor.addColorStop(.22,'#363a30');floor.addColorStop(1,'#171c19');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
 // distant silhouettes
 ctx.fillStyle='#28342e';ctx.beginPath();ctx.moveTo(0,horizon);for(let x=0;x<=W;x+=55)ctx.lineTo(x,horizon-rand(6,42));ctx.lineTo(W,horizon);ctx.fill();
 const fov=1.02,step=Math.max(2,Math.floor(W/520));zbuf=new Array(Math.ceil(W/step)+1).fill(30);
 for(let sx=0,ci=0;sx<W;sx+=step,ci++){let rayA=player.a+(sx/W-.5)*fov,rx=Math.cos(rayA),ry=Math.sin(rayA);let mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(rx||.00001)),ddy=Math.abs(1/(ry||.00001)),stepX=rx<0?-1:1,stepY=ry<0?-1:1,sdx=(rx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(ry<0?player.y-my:my+1-player.y)*ddy,side=0,dist=25;
 for(let k=0;k<50;k++){if(sdx<sdy){sdx+=ddx;mx+=stepX;side=0}else{sdy+=ddy;my+=stepY;side=1}if(mx<0||my<0||mx>=GW||my>=GH)break;if(grid[my][mx]==='#'){dist=side===0?(mx-player.x+(1-stepX)/2)/(rx||.0001):(my-player.y+(1-stepY)/2)/(ry||.0001);break}}
 dist=Math.max(.08,Math.abs(dist)*Math.cos(rayA-player.a));zbuf[ci]=dist;let wh=Math.min(H*1.6,H/(dist*.82)),top=horizon-wh*.5;let hit=side===0?player.y+dist*ry:player.x+dist*rx;let stripe=Math.floor((hit-Math.floor(hit))*12);let light=clamp(1-dist/13,.17,1)*(side===0?.85:1);let base=['#657263','#737867','#5e6a5e','#6e6c5a'][Math.floor(hit*2+side)%4];ctx.fillStyle=base;ctx.globalAlpha=light;ctx.fillRect(sx,top,step+1,wh);ctx.globalAlpha=1;if(stripe===0||stripe===11){ctx.fillStyle='#222a24';ctx.globalAlpha=light*.5;ctx.fillRect(sx,top,step+1,wh);ctx.globalAlpha=1}ctx.fillStyle='rgba(12,17,14,.14)';for(let yy=top+10;yy<top+wh;yy+=19)ctx.fillRect(sx,yy,step+1,1);
 }
 // ground marks and environmental props
 ctx.globalAlpha=.22;for(let i=0;i<18;i++){let x=(i*173+performance.now()*.012)%W;let y=horizon+((i*71)%Math.max(1,H-horizon));ctx.fillStyle=i%2?'#a4a083':'#101712';ctx.fillRect(x,y,rand(9,42),2)}ctx.globalAlpha=1;
 drawSprites(fov,step);
 // weapon silhouette
 let kick=performance.now()<fireAt+100?8:0;ctx.fillStyle='#111614';ctx.beginPath();ctx.moveTo(W*.42,H);ctx.lineTo(W*.44,H*.82+kick);ctx.lineTo(W*.55,H*.81+kick);ctx.lineTo(W*.61,H);ctx.fill();ctx.fillStyle='#303a33';ctx.fillRect(W*.467,H*.81+kick, W*.085, H*.19);ctx.fillStyle='#697568';ctx.fillRect(W*.51,H*.78+kick,5,H*.14);ctx.fillStyle='#202722';ctx.fillRect(W*.455,H*.9+kick,W*.1,H*.1);
 if(performance.now()<fireAt+70){ctx.fillStyle='#ffd992';ctx.beginPath();ctx.moveTo(W*.5,H*.78);ctx.lineTo(W*.48,H*.72);ctx.lineTo(W*.5,H*.66);ctx.lineTo(W*.52,H*.73);ctx.fill()}
}
function drawSprites(fov,step){let list=[];for(const e of enemies)if(e.alive)list.push({...e,sprite:'enemy'});for(const i of items)if(!i.taken)list.push({...i,sprite:i.type});list.sort((a,b)=>Math.hypot(b.x-player.x,b.y-player.y)-Math.hypot(a.x-player.x,a.y-player.y));for(const s of list){let dx=s.x-player.x,dy=s.y-player.y,d=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)-player.a;while(angle>Math.PI)angle-=Math.PI*2;while(angle< -Math.PI)angle+=Math.PI*2;if(Math.abs(angle)>fov*.72||d<.22)continue;let sx=(.5+angle/fov)*W,ci=Math.floor(sx/step);if(d>=(zbuf[ci]||30)+.15)continue;let scale=H/(d*.82),bottom=H*.50+scale*.49,size=clamp(scale*.11,5,85);
 if(s.sprite==='enemy'){let h=size*4,w=size*1.55;ctx.fillStyle='#111713';ctx.fillRect(sx-w*.5,bottom-h*.28,w,h*.28);ctx.fillStyle='#544d3d';ctx.fillRect(sx-w*.43,bottom-h,w*.86,h*.68);ctx.fillStyle='#7d7154';ctx.fillRect(sx-w*.38,bottom-h*.91,w*.76,h*.22);ctx.fillStyle='#252e28';ctx.fillRect(sx-w*.48,bottom-h*.41,w*.96,h*.15);ctx.fillStyle='#bd5142';ctx.fillRect(sx-w*.22,bottom-h*.84,w*.1,3);ctx.fillRect(sx+w*.12,bottom-h*.84,w*.1,3);ctx.fillStyle='#34372e';ctx.fillRect(sx-w*.65,bottom-h*.63,w*.2,h*.45);ctx.fillRect(sx+w*.45,bottom-h*.63,w*.2,h*.45);if(s.alert>0){ctx.fillStyle='#ff7766';ctx.beginPath();ctx.arc(sx,bottom-h*1.12,3,0,7);ctx.fill()}}
 else if(s.sprite==='loot'){ctx.fillStyle='#16211b';ctx.fillRect(sx-size,bottom-size*1.1,size*2,size*1.1);ctx.fillStyle='#b69254';ctx.fillRect(sx-size*.9,bottom-size*1.06,size*1.8,size*.72);ctx.fillStyle='#e2c47d';ctx.fillRect(sx-size*.9,bottom-size*.48,size*1.8,size*.13);ctx.fillStyle='#303e32';ctx.fillRect(sx-size*.22,bottom-size*.87,size*.44,size*.22);ctx.fillStyle='#d3b86f';ctx.fillRect(sx-size*.08,bottom-size*.85,size*.16,size*.17)}
 else {ctx.globalAlpha=.35+Math.sin(performance.now()*.006)*.13;ctx.fillStyle='#a7ff67';ctx.fillRect(sx-size*.8,bottom-size*5,Math.max(2,size*.08),size*5);ctx.globalAlpha=.9;ctx.strokeStyle='#c8f169';ctx.lineWidth=2;ctx.beginPath();ctx.arc(sx,bottom-size*.6,size*.7,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#e0ff9c';ctx.beginPath();ctx.arc(sx,bottom-size*.6,3,0,7);ctx.fill()}
 }}

